// Mini lector de marcado: etiquetas con cierre, atributos como texto y contenido. No es un navegador.
function leer(html) {
  const raiz = { etiqueta: 'documento', atributos: '', hijos: [] };
  const pila = [raiz];
  const re = /<(\/?)([a-z0-9]+)([^>]*)>|([^<]+)/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const actual = pila[pila.length - 1];
    if (m[4] !== undefined) {
      const texto = m[4].trim();
      if (texto) actual.hijos.push({ etiqueta: '#texto', atributos: texto, hijos: [] });
    } else if (m[1] === '/') {
      pila.pop();
    } else {
      const nodo = { etiqueta: m[2].toLowerCase(), atributos: m[3].trim(), hijos: [] };
      actual.hijos.push(nodo);
      pila.push(nodo);
    }
  }
  return raiz;
}

function mostrar(nodo, nivel = 0) {
  const sangria = '  '.repeat(nivel);
  if (nodo.etiqueta === '#texto') console.log(sangria + '"' + nodo.atributos + '"');
  else console.log(sangria + '<' + nodo.etiqueta + '>' + (nodo.atributos ? '  [' + nodo.atributos + ']' : ''));
  nodo.hijos.forEach((h) => mostrar(h, nivel + 1));
}

function contar(nodo, nombre) {
  return (nodo.etiqueta === nombre ? 1 : 0) + nodo.hijos.reduce((suma, h) => suma + contar(h, nombre), 0);
}

const bien = '<ul><li class="demorado">R-1003</li><li>R-1001</li></ul>';
const arbol = leer(bien);
mostrar(arbol);
console.log('cantidad de li:', contar(arbol, 'li'));

console.log('--- con un párrafo sin cerrar ---');
mostrar(leer('<p>uno<p>dos'));

