// Un programa que escribe marcado: de una lista de datos a un fragmento de HTML.
function escapar(texto) {
  return String(texto)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function filaHTML(envio) {
  const clase = envio.estado.toLowerCase().replaceAll(' ', '-');
  return '<tr><td>' + escapar(envio.remito) + '</td><td>' + escapar(envio.destino) +
    '</td><td class="' + clase + '">' + escapar(envio.estado) + '</td></tr>';
}

const envios = [
  { remito: 'R-1001', destino: 'Palermo', estado: 'En camino' },
  { remito: 'R-1002', destino: 'Caballito', estado: 'Entregado' },
  { remito: 'R-1003', destino: 'Belgrano <b>', estado: 'Demorado' },
];

